-- Port centroid seed for lit_geo_place_centroids (one-time, idempotent).
--
-- Geocodes the ~459 distinct ports referenced by
-- lit_company_port_lanes (OSM via photon.komoot.io, 2026-08-19) so the
-- company-profile map can draw port-level lanes.
--
-- Key format (must match frontend/src/api/portLanes.ts):
--   exit ports:  port:<lower exit_port>|<lower exit_port_country>
--   entry ports: port:<lower entry_port>
--
-- precision='failed' rows (junk buckets like "All Other X Ports",
-- "Panama Canal", numeric codes, or genuine geocode misses) carry NULL
-- coords and are ignored by consumers — seeded anyway so the batch job
-- and future re-runs know they were attempted.
--
-- 398 geocoded / 61 failed.

on conflict (place_key) do update set
  city = excluded.city,
  region = excluded.region,
  country = excluded.country,
  lat = excluded.lat,
  lng = excluded.lng,
  "precision" = excluded."precision",
  source = excluded.source;
